// Matches an <a> tag, capturing the opening tag, the href value, the link text and the
// closing tag separately so that only the link text can be swapped out.
private final static Pattern A_TAG_PATTERN = Pattern.compile(
        "(<a\\s[^>]*href\\s*=\\s*\"([^\"]*)\"[^>]*>)(.*?)(</a>)",
        Pattern.CASE_INSENSITIVE | Pattern.DOTALL);

/**
 * Hacker News shortens the visible text of long links and ends it with an ellipsis, while the
 * href still points at the complete url. That is fine when reading, but if the text is meant to
 * be selected and copied we want the whole link to be present. This replaces the text of every
 * link which has been truncated that way with the full url from its href.
 */
public static String expandTruncatedLinks(String html) {
    if (TextUtils.isEmpty(html)) {
        return html;
    }

    Matcher matcher = A_TAG_PATTERN.matcher(html);
    StringBuffer result = new StringBuffer();

    while (matcher.find()) {
        String openingTag = matcher.group(1);
        String href = matcher.group(2);
        String linkText = matcher.group(3);
        String closingTag = matcher.group(4);

        // The href is kept escaped exactly as it appeared in the html, that way entities such
        // as &#x2F; are decoded the same way as before when the text gets parsed.
        String newLinkText = isTruncatedLink(linkText, href) ? href : linkText;

        matcher.appendReplacement(result,
                Matcher.quoteReplacement(openingTag + newLinkText + closingTag));
    }
    matcher.appendTail(result);

    return result.toString();
}

private static boolean isTruncatedLink(String linkText, String href) {
    if (TextUtils.isEmpty(linkText) || TextUtils.isEmpty(href)) {
        return false;
    }

    String text = fromHtml(linkText).trim();

    String withoutEllipsis;
    if (text.endsWith("...")) {
        withoutEllipsis = text.substring(0, text.length() - 3);
    } else if (text.endsWith("\u2026")) {
        withoutEllipsis = text.substring(0, text.length() - 1);
    } else {
        // Not truncated, leave it alone
        return false;
    }

    if (TextUtils.isEmpty(withoutEllipsis)) {
        return false;
    }

    // Only expand if the visible text really is the beginning of the url, so that links with
    // an actual title which happens to end with an ellipsis are left untouched.
    return stripScheme(fromHtml(href).trim()).startsWith(stripScheme(withoutEllipsis));
}

private static String fromHtml(String html) {
    return HtmlCompat.fromHtml(html, HtmlCompat.FROM_HTML_MODE_LEGACY).toString();
}

private static String stripScheme(String url) {
    if (url.startsWith("https://")) {
        return url.substring(8);
    } else if (url.startsWith("http://")) {
        return url.substring(7);
    }
    return url;
}

